function ActivitySkinTrialNode:RequestSubActivity(subId)
    GameUtils.Request('activity2/skinCardExperience', { activityUuid = subId }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
    
        self._homeData = checkTable(response.data)

        local activityDojo = ActivityUtils.GetSubActivityDojo(self._collectionDojo, subId)
        self:RefreshUI(activityDojo)
    end)
end
