---入口点击回调
function ActivitySkinTrialNode:EntryOnClickHandler()
    local subId = self:GetSubId()
    xRecord.record('6-005', string.format('enter_activity_page_%d', checkInt(subId)))
    UIModule.OpenDialog(
            {
                id = Constants.UITypeIds.UIFightTeamChoose,
                parameters = { levelId = self._homeData.cardExperience.questId, activityUuid = subId }
            },
            {
                { id = Constants.UITypeIds.UIActivityMainDialog }
            }
    )
end

---领取按钮点击回调
function ActivitySkinTrialNode:BtnReceiveOnClickHandler()
    local getStatus = checkInt(self._homeData.rewardsStatus)
    if getStatus ~= Constants.GetStatus.Can then
        if getStatus == Constants.GetStatus.Not then
            GameUtils.Toast(localize("请先通关战斗训练"))
        elseif getStatus == Constants.GetStatus.Has then
            GameUtils.Toast(localize("已经领取过了"))
        end
        return
    end

    local subId = self:GetSubId()
    GameUtils.Request('activity2/skinCardExperienceDraw', { activityUuid = subId }, function(request, response)
        GoodsUtils.DrawRewards(response.data.rewards)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = response.data.rewards } })

        self._homeData.rewardsStatus = Constants.GetStatus.Has
        local datas = self._collectionDojo.collectionDatas
        for i, data in ipairs(datas) do
            if checkNumber(data.id) == subId then
                data.isDrawRewards = Constants.GetStatus.Has
            end
        end
        Events.Broadcast(Constants.EventNames.ActivityRedPointChange, subId, -1)
        self:RefreshRewardGroup()
        self:RefreshRoleList()
    end)
end
--endregion handler

--region public
---刷新自身
---@param activityDojo ActivityDojo
function ActivitySkinTrialNode:Refresh(collectionDojo)
    self._collectionDojo = collectionDojo
    
    local subId = self:GetSubId()
    local activityDojo = ActivityUtils.GetSubActivityDojo(self._collectionDojo, subId)
    local t = checkTable(activityDojo.unlock)
    if table.count(t) > 0 then
        local vo = t[1]
        local isUnlock = GameUtils.IsUnlockedSingle(vo.targetType, vo.targetNum, vo.targetId)
        local entryLockGroupTrans = self.BtnEntry.transform.parent:Find("BtnLock")
        if entryLockGroupTrans then
            CfUtils.SetActive(entryLockGroupTrans, not isUnlock)
            local err = GameUtils.GetUnlockDescr(vo.targetType, vo.targetNum, vo.targetId)
            SetButtonAction(entryLockGroupTrans, function()
                GameUtils.Toast(localize('_name_解锁', {_name_ = tostring(err)}))
            end)
            CfUtils.FillText(entryLockGroupTrans:Find("Layout/TextEnter"),  localize('_name_解锁', {_name_ = tostring(err)}))
        end
        CfUtils.SetActive(self.BtnEntry, isUnlock)
    end
    self:RequestSubActivity(subId)
    --self:RefreshUI(activityDojo)
end
--endregion public

--region private
---刷新UI
---@param activityDojo ActivityDojo
function ActivitySkinTrialNode:RefreshUI(activityDojo)
    self.activityDojo = activityDojo
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(activityDojo.startTime, activityDojo.endTime))
    CfUtils.FillText(self.TxtContent, activityDojo.detail)
    CfUtils.FillText(self.BtnTxtTime, localize("距离结束:_time_", { _time_ = ActivityUtils.ConventLeftTimeText(activityDojo.endTime) }))

    local skinId = checkInt(self._homeData.cardExperience.rewardId)
    local cardSkinVo = CfUtils.GetCfVo(AutoIds.IdSetting113, "CardSkinVo", skinId)
    local roleId = cardSkinVo.roleId

    -- 刷新立绘
    -- if self._homeData.cardExperience.rewardImg then
    --     CfUtils.FillImage(self.ImgRole1, ActivityUtils.GetImageFullPath(self._homeData.cardExperience.rewardImg))
    -- end
    if self:NeedSwitchAnim() then
        self.Anim_RoleGroup:Stop()
        self.Anim_RoleGroup:Play("ActivityTryOutPanel110002_RoleSwitch")
        self:StopShowRoleCo()
        self.co_ShowRoleImg = CoStart(function()
            CoYield(0.2)
            self.DN_RoleImg:Execute(skinId)
            CfUtils.SetActive(self.DN_RoleImg.gameObject, true)
            self.co_ShowRoleImg = nil
        end)
    else
        self.DN_RoleImg:Execute(skinId)
        CfUtils.SetActive(self.DN_RoleImg.gameObject, true)
    end
    CfUtils.SetActive(self.Anim_RoleGroup, true)
    KTool.SetActive(self.BtnRoleNameNode, true)
    ---@type CommonBtnRoleNameNode
    local env = CfUtils.GetLuaScr(self.BtnRoleNameNode, "Game.UI.Common.CommonBtnRoleNameNode")
    if env then
        env:RefreshSelf(skinId, nil, function()
            KCookie.Set(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_SELECTED_ACTIVITY_ID, self._collectionDojo.id)
            ActivityUtils.SetSubActivityId(activityDojo.id)
        end, true, self:NeedSwitchAnim())
    end

    -- 网络标题
    local titleImgUrl = checkString(activityDojo.titleImage)
    if string.len(titleImgUrl) > 0 then
        CfUtils.FillWebRawImage(self.ImgTitle, titleImgUrl)
    end

    self:RefreshRewardGroup()
    self:RefreshRoleList()
    
    self:SetNeedSwitchAnim(false)
end

---刷新奖励
function ActivitySkinTrialNode:RefreshRewardGroup()
    local status = checkInt(self._homeData.rewardsStatus)

    local canGet = status == Constants.GetStatus.Can
    local isGet = status == Constants.GetStatus.Has
    local rewards = self._homeData.cardExperience.rewards

    KTool.SetActive(self.RewardGroup, true)
    KTool.SetActive(self.BtnReceiveGroup, true)
    local fontStyleBtn = self.BtnReceive:GetComponent(typeof(FontStyleButton))
    fontStyleBtn:ResetFontStyle(canGet and "B25" or "B18", isGet and localize("已领取") or localize("领取"))

    local RT_GoodNode = self.CommonGoodsListLight
    ---@type CommonGoodsListLight
    local LB_GoodNode = CfUtils.GetLuaScr(RT_GoodNode.gameObject, "Game.Behaviours.CommonGoodsListLight")
    LB_GoodNode:FreshBaseUI(rewards, canGet, isGet, true, false, false, false)
end

function ActivitySkinTrialNode:RefreshRoleList()
    local rootGO = self.CombatantBtnHeadGroup.gameObject
    local itemGO = self.ItemNode.gameObject

    local childCount = rootGO.transform.childCount
    local subId = self:GetSubId()

    local datas = self._collectionDojo.collectionDatas
    for i, data in ipairs(datas) do
        local go
        if i <= childCount then
            go = rootGO.transform:GetChild(i - 1).gameObject
        else
            go = KTool.Instantiate(rootGO, itemGO)
        end
        KTool.SetActive(go, true)

        -- 头像按钮
        local btn = go.transform:Find("HotpointNewCombatantBtnHead")
        ---@type HotPointCollectionNewCombatantBtnHead
        local lt = GetLuaBehaviour(btn.gameObject, btnHeadLuaPath).Env

        ---@type CardSkinVo
        local skinVo = cardConfMgr:GetCardSkinBySkinId(checkNumber(data.skinId))
        lt:FreshUI({cardId = skinVo.roleId,  skinId = skinVo.skinId})
        lt:FreshSelectState(data.id == subId)
        lt:SetCallback(function()
            ActivityUtils.SetSubActivityId(data.id)
            self:SetNeedSwitchAnim(true)
            self:Refresh(self._collectionDojo)
        end)

        -- 红点
        local redPoint = go.transform:Find("redPoint")
        KTool.SetActive(redPoint, data.redDotHint >= 0)

        -- 领取状态
        local isDraw = checkNumber(data.isDrawRewards)
        local imgFinish = go.transform:Find("ImgFinish")
        KTool.SetActive(imgFinish, isDraw == Constants.GetStatus.Has)
    end
end

function ActivitySkinTrialNode:GetSubId()
    local subId = checkNumber(ActivityUtils.GetSubActivityId())
    -- 检查之前记录的subId是否是这个集合里的id
    local datas = self._collectionDojo.collectionDatas
    for i, v in ipairs(datas) do
        if v.id == subId then
            return subId
        end
    end
    return datas[1].id
end

function ActivitySkinTrialNode:StopShowRoleCo()
    if isNotNull(self.co_ShowRoleImg) then
        CoStop(self.co_ShowRoleImg)
        self.co_ShowRoleImg = nil
    end
end

function ActivitySkinTrialNode:SetNeedSwitchAnim(need)
    self.needSwitchAnim = need
end

function ActivitySkinTrialNode:NeedSwitchAnim()
    if isNull(self.needSwitchAnim) then
        return false
    else
        return self.needSwitchAnim
    end
end
--endregion private

function ActivitySkinTrialNode:OnBtnArrowClick()
    local jumpId = self._homeData.cardExperience.jumpType == 1 and 864 or 1110
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    local row = goodsConfMgr:GetJumpModuleRow(jumpId)
    goodsConfMgr:ExecuteJump(row)
end

return ActivitySkinTrialNode